<script lang="ts">
 import {app} from '../lib/state/app.svelte';import * as bridge from '../lib/api/bridge';import {initials,providerText} from '../lib/format';import Icon from '../lib/components/Icon.svelte';
 type Tab='appearance'|'gateway'|'profiles'|'privacy'|'runtime';const tab=$derived(app.settingsSection);let port=$state(''),restarting=$state(false),selectedProfile=$state('');
 const sections:Array<{id:Tab;label:string}>=[{id:'appearance',label:'Appearance'},{id:'gateway',label:'Local gateway'},{id:'profiles',label:'Website profiles'},{id:'privacy',label:'Privacy & diagnostics'},{id:'runtime',label:'Runtime'}];
 const profile=$derived(app.providers.find(p=>p.id===Number(selectedProfile))??app.provider??app.providers[0]);
 async function doRestart(){restarting=true;try{await bridge.restart();return true;}catch(error){app.error=String(error);app.popupError=app.error;return false;}finally{restarting=false;}}
 async function restart(){
  if(app.sessions.some(s=>s.status==='ACTIVE')||app.activeTask){await app.ask('Restart and interrupt active work?','Active client requests and website tool tasks will be interrupted. Saved profiles will be reloaded.','Restart backend',async()=>await doRestart()?true:undefined);}
  else await doRestart();
 }
 async function applyPort(){if(await app.settings({port:Number(port)}))port='';}
 async function updateProfile(key:string,value:unknown){if(profile)await app.perform('provider.update',{provider_id:profile.id,[key]:value});}
</script>
<section class="screen"><div class="screen-inner"><header class="screen-head"><div><div class="breadcrumb">Workspace / Preferences</div><h1>Settings</h1><p>Changes are saved by the Zag backend. Browser permissions remain explicit.</p></div></header><div class="preferences-layout"><nav class="preferences-nav" aria-label="Settings sections">{#each sections as section}<button class:active={tab===section.id} aria-current={tab===section.id?'page':undefined} onclick={()=>app.settingsSection=section.id}>{section.label}</button>{/each}</nav><div>
{#if tab==='appearance'}
 <section class="section"><h2>Appearance</h2><div class="setting-row"><div><strong>Color theme</strong><p>Use a light workspace, a dark workspace, or follow your system.</p></div><div class="segmented">{#each ['dark','light','system'] as theme}<button class:active={app.preferences.theme===theme} aria-pressed={app.preferences.theme===theme} aria-label={`${theme} theme`} disabled={!app.ready} onclick={()=>app.settings({theme:theme as 'dark'|'light'|'system'})}><Icon name={theme==='dark'?'moon':theme==='light'?'sun':'monitor'} size={15}/>{theme[0].toUpperCase()+theme.slice(1)}</button>{/each}</div></div><div class="setting-row"><div><strong>Compact density</strong><p>Reduce spacing in tables and settings.</p></div><button class="toggle" role="switch" aria-label="Compact density" aria-checked={app.preferences.compact} disabled={!app.ready} onclick={()=>app.settings({compact:!app.preferences.compact})}></button></div><div class="setting-row"><div><strong>Connection inspector</strong><p>Show mappings and session details beside the website.</p></div><button class="toggle" role="switch" aria-label="Connection inspector" aria-checked={app.inspectorVisible} onclick={()=>{app.inspectorVisible=!app.inspectorVisible;app.saveLayout();}}></button></div></section><section class="section"><h2>Startup & tabs</h2><div class="setting-row"><div><strong>Restore website tabs</strong><p>Reopen your previous website tabs when the application starts. Their isolated login profiles are retained either way.</p></div><button class="toggle" role="switch" aria-label="Restore website tabs" aria-checked={app.preferences.restore_tabs} disabled={!app.ready} onclick={()=>app.settings({restore_tabs:!app.preferences.restore_tabs})}></button></div><div class="setting-row"><div><strong>Launch at login</strong><p>Register this application in your Linux desktop’s user autostart directory.</p></div><button class="toggle" role="switch" aria-label="Launch at login" aria-checked={app.preferences.auto_start} disabled={!app.ready} onclick={()=>app.settings({auto_start:!app.preferences.auto_start})}></button></div><div class="setting-row"><div><strong>Sleep inactive websites</strong><p>Unload idle background webviews. Active requests, the current tab, and kept-awake websites stay awake.</p></div><select aria-label="Idle website timeout" value={app.preferences.idle_minutes} disabled={!app.ready} onchange={event=>app.settings({idle_minutes:Number(event.currentTarget.value)})}><option value="0">Never</option><option value="5">After 5 minutes</option><option value="15">After 15 minutes</option><option value="30">After 30 minutes</option><option value="60">After 1 hour</option><option value="120">After 2 hours</option></select></div></section>
{:else if tab==='gateway'}
 <section class="section"><h2>Local gateway</h2><div class="setting-row"><div><strong>Accept client connections</strong><p>Stop cancels active inference and closes the local HTTP listener. The desktop browser remains usable.</p></div><button class="toggle" role="switch" aria-label="Accept client connections" aria-checked={app.snapshot?.api.running??false} disabled={!app.ready} onclick={()=>app.snapshot?.api.running?app.ask('Stop the local gateway?','This cancels connected client requests. Website tabs and login data are kept.','Stop gateway',()=>app.perform('api.stop')):app.perform('api.start')}></button></div><div class="setting-row"><div><strong>Listening port</strong><p>Only 127.0.0.1 is allowed. Changing ports preserves existing requests until they finish.</p></div><form class="inline" onsubmit={event=>{event.preventDefault();void applyPort();}}><input type="number" aria-label="Gateway port" value={port||app.snapshot?.api.port||7331} oninput={event=>port=event.currentTarget.value} min="1024" max="65535" required/><button class="secondary" disabled={!app.ready||!port||Number(port)===(app.snapshot?.api.port)||app.busy('settings.update')}>Apply</button></form></div><div class="setting-row"><div><strong>Local API key</strong><p>Regeneration revokes the old key and terminates connected clients. Website credentials are unaffected.</p></div><button class="secondary" disabled={!app.ready} onclick={()=>app.showPopup('rotate-key')}><Icon name="key" size={14}/>Regenerate</button></div><div class="setting-row"><div><strong>Default model alias</strong><p>Requests for <code>bridge/default</code> route to this explicitly selected model.</p></div><select aria-label="Default gateway model" value={app.preferences.default_model} disabled={!app.ready} onchange={event=>app.settings({default_model:event.currentTarget.value})}><option value="">No default selected</option>{#each app.models as m}<option value={m.id} disabled={!m.enabled||!m.available||!m.provider.exposed||m.provider.state!=='READY'}>{m.provider.label} / {m.display_name}</option>{/each}</select></div></section>
 <section class="section"><h2>Explicit fallback</h2><div class="setting-row"><div><strong>Fallback model</strong><p>Choose another available model for new sessions only. Existing conversations are never silently moved between websites.</p></div><select aria-label="Fallback model" value={app.preferences.fallback_model} disabled={!app.ready} onchange={event=>app.settings({fallback_model:event.currentTarget.value,fallback_enabled:!!event.currentTarget.value&&app.preferences.fallback_enabled})}><option value="">No fallback selected</option>{#each app.models as m}<option value={m.id} disabled={!m.enabled||!m.available||!m.provider.exposed||m.provider.state!=='READY'}>{m.provider.label} / {m.display_name}</option>{/each}</select></div><div class="setting-row"><div><strong>Allow fallback before dispatch</strong><p>Only before a prompt is submitted, when the selected website reports a limit or is unavailable. No retry after generation begins.</p></div><button class="toggle" role="switch" aria-label="Allow fallback" aria-checked={app.preferences.fallback_enabled} disabled={!app.ready||!app.preferences.fallback_model} onclick={()=>app.settings({fallback_enabled:!app.preferences.fallback_enabled})}></button></div><div class="note"><Icon name="shield" size={15}/><span>Fallback follows your explicit routing policy; it does not bypass a provider’s quota or create additional accounts.</span></div></section>
{:else if tab==='profiles'}
 <section class="section"><div class="section-title"><h2>Website profiles</h2><button class="secondary" disabled={!app.ready} onclick={()=>app.showPopup('add')}><Icon name="plus" size={13}/>Add website</button></div><label class="field"><span>Website</span><select aria-label="Website profile" value={profile?.id??''} onchange={event=>selectedProfile=event.currentTarget.value}>{#if !app.providers.length}<option value="">No saved website profiles</option>{/if}{#each app.providers as p}<option value={p.id}>{p.label} · {p.origin}</option>{/each}</select></label>{#if profile}<div class="setting-row"><div><strong>Display name</strong><p>{profile.origin}</p></div><input aria-label="Website display name" value={profile.label} maxlength="120" disabled={profile.active} onchange={event=>updateProfile('label',event.currentTarget.value)}/></div><div class="setting-row"><div><strong>Keep this website awake</strong><p>Kept-awake profiles are excluded from idle suspension.</p></div><button class="toggle" role="switch" aria-label="Keep website awake" aria-checked={profile.pinned} onclick={()=>updateProfile('pinned',!profile.pinned)}></button></div>{#if profile.detected&&!profile.dismissed}<div class="setting-row"><div><strong>Model and reasoning options</strong><p>Exposure, context overrides and model preferences live in Provider settings.</p></div><button class="secondary" onclick={()=>{app.providerSelection=profile.id;app.navigate('providers');}}>Provider settings</button></div>{/if}<div class="setting-row"><div><strong>Clear local profile</strong><p>Delete this website’s local storage and sign out of this profile. Remote account data is not deleted.</p></div><button class="secondary" onclick={()=>app.showPopup('clear-profile',profile.id)}>Clear storage</button></div><div class="setting-row"><div><strong>Remove website</strong><p>Remove the profile and connector from the workspace and end associated sessions.</p></div><button class="secondary danger-text" onclick={()=>app.showPopup('remove-provider',profile.id)}>Remove</button></div>{:else}<p>No website profiles have been added.</p>{/if}</section>
{:else if tab==='privacy'}
 <section class="section"><h2>Privacy boundaries</h2><div class="setting-row"><div><strong>Provider authentication</strong><p>Passwords, cookies, OAuth tokens, and authentication headers remain in website-owned browser storage. Instrumentation does not extract them.</p></div><Icon name="lock" size={17}/></div><div class="setting-row"><div><strong>Conversation storage</strong><p>Session IDs, conversation URLs, and SHA-256 message receipts persist locally. Prompt bodies and tool results are not written to session files.</p></div><span class="tag">Metadata only</span></div><div class="setting-row"><div><strong>Raw payload capture</strong><p>Raw network payload and credential capture are not enabled by any preference in this build.</p></div><span class="tag">Disabled</span></div></section><section class="section"><h2>Diagnostics</h2><div class="setting-row"><div><strong>Log level</strong><p>Debug adds bounded structural browser events. Authentication values and form data remain excluded.</p></div><select aria-label="Log level" value={app.preferences.logging} onchange={event=>app.settings({logging:event.currentTarget.value as 'ERROR'|'WARN'|'INFO'|'DEBUG'})}>{#each ['ERROR','WARN','INFO','DEBUG'] as level}<option value={level}>{level}</option>{/each}</select></div><div class="setting-row"><div><strong>Developer diagnostics</strong><p>Enable authenticated debug endpoints and allow the native page inspector. This never grants arbitrary commands to provider pages.</p></div><button class="toggle" role="switch" aria-label="Developer diagnostics" aria-checked={app.preferences.developer_mode} disabled={!app.ready} onclick={()=>app.settings({developer_mode:!app.preferences.developer_mode})}></button></div><div class="setting-row"><div><strong>Retained diagnostic events</strong><p>The ring holds at most 160 redacted records and is cleared when the backend exits.</p></div><button class="secondary" disabled={!app.events.length} onclick={()=>app.perform('logs.clear')}>Clear events</button></div></section>
{:else}
 <section class="section"><h2>Desktop runtime</h2><div class="setting-row"><div><strong>Zag sidecar</strong><p>{app.host.code||'The native backend owns routing, protocol translation, sessions, discovery, and the loopback server.'}</p></div><span class="tag" class:ready={app.host.state==='READY'}><span class="dot" class:online={app.host.state==='READY'}></span>{app.host.state}</span></div><div class="setting-row"><div><strong>Backend version</strong><p>Protocol version 1 · Linux x86-64 distribution target</p></div><code>{app.snapshot?.version||'Not connected'}</code></div><div class="setting-row"><div><strong>Restart backend</strong><p>Cancel current requests, restart the sidecar, reload saved metadata, and reconnect the trusted UI. Provider profiles remain on disk.</p></div><button class="secondary" disabled={restarting} onclick={restart}><Icon name="refresh" size={14}/>{restarting?'Restarting…':'Restart Zag'}</button></div><div class="setting-row"><div><strong>Keyboard controls</strong><p>Review the desktop shortcuts and website-focus behavior.</p></div><button class="secondary" onclick={()=>app.showPopup('shortcuts')}>View shortcuts</button></div></section><section class="section"><h2>Research detector</h2><p style="margin-top:15px">{app.snapshot?.detector.reason||'No qualified TNN artifact is loaded. Symbolic discovery remains authoritative.'}</p><div class="note"><Icon name="shield" size={16}/><span>TNN action proposals must pass the same bounded browser action validator. An unqualified detector cannot take over production behavior.</span></div></section>
{/if}
</div></div></div></section>
